    updateItemQuantity,
    isRecommendedSection,
    isRecommendedItem,
    getSectionDisplayName,
    normalizeMenuCategoryId,
    toRenderableArray,
    getSectionCategoryImage,
    menuCategories,
    getActiveFilterCount,
    activeFilterCount,
    handleBookmarkClick,
